/**
 * @name Regular expression injection
 * @description Using untrusted input in regular expressions can lead to ReDoS or other issues
 * @kind path-problem
 * @problem.severity warning
 * @id py/regex-injection
 * @tags security
 *        external/cwe/cwe-1333
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module RegexInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Find re.compile, re.search, re.match, re.findall, re.sub, etc.
    exists(API::CallNode call |
      (
        call = API::moduleImport("re").getMember("compile").getACall() or
        call = API::moduleImport("re").getMember(["search", "match", "findall", "finditer", "sub", "subn"]).getACall()
      ) and
      // The pattern argument is the first argument for most re functions
      sink = call.getArg(0)
    )
  }
}

module RegexInjectionFlow = TaintTracking::Global<RegexInjectionConfig>;
import RegexInjectionFlow::PathGraph

from RegexInjectionFlow::PathNode source, RegexInjectionFlow::PathNode sink
where RegexInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Regular expression injection from $@.", source.getNode(), "user input"

/**
 * @name SQL injection
 * @description Using database queries with untrusted input can lead to SQL injection
 * @kind path-problem
 * @problem.severity error
 * @id py/sql-injection
 * @tags security
 *        external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module SqlInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Find SQL execution calls
    exists(API::CallNode call |
      // sqlite3 module
      call = API::moduleImport("sqlite3").getMember(["execute", "executemany"]).getACall() or
      // MySQL connector
      call = API::moduleImport("mysql").getMember(["execute", "executemany"]).getACall() or
      call = API::moduleImport("MySQLdb").getMember(["execute", "executemany"]).getACall() or
      // PostgreSQL
      call = API::moduleImport("psycopg2").getMember(["execute", "executemany"]).getACall() or
      // Generic database modules
      call = API::moduleImport("db").getMember(["execute", "executemany"]).getACall() or
      call = API::moduleImport("pymysql").getMember(["execute", "executemany"]).getACall()
    |
      sink = call.getArg(0)  // First argument is the SQL query
    )
  }
}

module SqlInjectionFlow = TaintTracking::Global<SqlInjectionConfig>;
import SqlInjectionFlow::PathGraph

from SqlInjectionFlow::PathNode source, SqlInjectionFlow::PathNode sink
where SqlInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SQL injection from $@.", source.getNode(), "user input"

